import{_ as i,o as e,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph in Scientific Computing and Large Clusters BoF","description":"","frontmatter":{"title":"Ceph in Scientific Computing and Large Clusters BoF","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Scientific Computing","Large Clusters","Distributed Storage","CRUSH Algorithm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_in_Scientific_Computing_and_Large_Clusters_BoF.md","filePath":"posts/2023/Ceph_in_Scientific_Computing_and_Large_Clusters_BoF.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_in_Scientific_Computing_and_Large_Clusters_BoF.md"};function o(l,t,s,g,u,h){return e(),r("div",null,[...t[0]||(t[0]=[a('<p>会议纪要</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>主持人</strong>: Kevin Herb Chuck</li><li><strong>会议类型</strong>: 科学研究计算大型集群的非正式讨论会（Birds of a Feather）</li><li><strong>目的</strong>: 促进对科学研究和计算环境中有相似兴趣的人员之间的交流与讨论。</li></ul><h3 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h3><ul><li><strong>参与者介绍</strong>: Kevin来自美国威斯康星大学的空间科学与工程中心，负责处理NASA多个任务的卫星数据。</li><li><strong>会议形式</strong>: 非正式讨论，主要围绕Ceph在大型集群中的应用、升级、问题解决以及用户经验分享。</li><li><strong>讨论主题</strong>: <ul><li><strong>Ceph版本升级</strong>: 讨论了从Red Hat 7到更高版本的升级路径，特别是从Nautilus到Octopus的升级挑战。</li><li><strong>集群管理</strong>: 涉及如何处理大规模集群的滚动重启和升级，以及如何优化故障域管理。</li><li><strong>S3 API应用</strong>: 讨论了如何为科学用户提供安全的S3 API访问，包括自定义前端和后端解决方案。</li><li><strong>数据管理</strong>: 分享了在大型集群中处理数据突增和异常增长的策略。</li></ul></li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li><strong>S3 API安全管理</strong>: 采用自定义前端和后端工具来管理S3凭证，确保科学用户的安全访问。</li><li><strong>集群升级策略</strong>: 探讨了通过虚拟机架和逐步升级策略来减少数据迁移的影响。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>持续交流</strong>: 定期举行线上Meetup，时间为每两个月的第四个星期三，下午4点（中欧时间）。</li><li><strong>信息共享</strong>: 通过Seth pad记录和分享每次会议的讨论内容和发现。</li></ul><h3 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h3><ul><li><strong>技术挑战</strong>: 讨论中提到了在大型集群中实施滚动重启和升级的技术挑战，以及如何通过改进Crush map和故障域管理来优化这些过程。</li><li><strong>社区合作</strong>: 鼓励参与者通过共享经验和合作开发开源API来解决共同面临的问题。</li><li><strong>集群规模</strong>: 参与者分享了他们的集群规模和使用的Ceph版本，包括从Firefly到Quincy的版本。</li><li><strong>操作系统升级</strong>: 讨论了在大型集群中进行操作系统升级的策略，包括先升级操作系统然后再升级Ceph集群。</li><li><strong>自动化和容器化</strong>: 讨论了使用Kubernetes和容器化技术来简化集群管理和升级。</li><li><strong>虚拟化</strong>: 讨论了使用虚拟化技术来提供更高的故障域和灵活性。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议成功促进了科学研究计算领域中Ceph用户的交流与合作，为解决共同的技术挑战提供了平台和机会。</p>',13)])])}const p=i(n,[["render",o]]);export{d as __pageData,p as default};
